import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, hash } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = THREE;

  const root = new Group();
  const inner = new Group();
  root.add(inner);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const cardW = 4.2;
  const cardH = 2.625;

  // --- Backdrop: engineered gradient surface + subtle grain ---
  const backW = 5.4, backH = 3.6;
  const backMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide, toneMapped: false });
  const gradNode = mix(color(surface), color(ink), uv().y);
  const grainNode = hash(uv().mul(950)).sub(0.5).mul(0.05);
  backMat.colorNode = gradNode.add(grainNode);
  const back = new Mesh(new PlaneGeometry(backW, backH), backMat);
  back.position.set(0, 0, -0.25);
  inner.add(back);

  // --- Machined ink frame behind card ---
  const frameMat = new MeshBasicNodeMaterial({ color: new Color(ink), toneMapped: false });
  const frame = new Mesh(new PlaneGeometry(cardW + 0.07, cardH + 0.07), frameMat);
  frame.position.set(0, 0.15, -0.01);
  inner.add(frame);

  // --- Image card ---
  const cardMat = new MeshBasicNodeMaterial({ transparent: true, toneMapped: false, side: DoubleSide });
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((t) => {
      t.colorSpace = THREE.SRGBColorSpace;
      cardMat.map = t;
      cardMat.needsUpdate = true;
    });
  }
  const card = new Mesh(new PlaneGeometry(cardW, cardH), cardMat);
  card.position.set(0, 0.15, 0);
  inner.add(card);

  // --- Accent line (signal red, <10% of frame) ---
  const accentMat = new MeshBasicNodeMaterial({ color: new Color(accent), toneMapped: false });
  const accentBar = new Mesh(new PlaneGeometry(1.2, 0.03), accentMat);
  accentBar.position.set(0, cardH / 2 + 0.15 + 0.28, 0.02);
  inner.add(accentBar);

  // --- Text content (rendered verbatim via fontAtlas) ---
  const textGroup = new Group();
  let ty = -cardH / 2 - 0.45;
  for (const item of items) {
    const fs = item.typography?.fontSize ?? 31;
    const t = ctx.fontAtlas.createText(String(item.text), {
      fontSize: fs,
      color: paper,
      align: 'center',
      maxWidthPx: 480,
      letterSpacingPx: 0.5,
    });
    t.position.set(0, ty, 0.05);
    textGroup.add(t);
    ty -= 0.4;
  }
  inner.add(textGroup);

  // --- Entrance: rise-in + weighted settle ---
  const tl = gsap.timeline();
  tl.from(inner.position, { y: 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  tl.from(inner.scale, { x: 0.97, y: 0.97, duration: 0.9, ease: 'power4.out' }, 0);

  // --- Handlers (static composition, no interactivity) ---
  root.userData.handlers = {};

  // --- Cleanup ---
  const mats = [backMat, cardMat, frameMat, accentMat];
  const geos = [back.geometry, card.geometry, frame.geometry, accentBar.geometry];
  root.userData.cleanup = () => {
    tl.kill();
    for (const m of mats) m.dispose();
    for (const g of geos) g.dispose();
    for (const c of textGroup.children) {
      if (c.geometry) c.geometry.dispose();
      if (c.material) c.material.dispose();
    }
  };

  return root;
}
